/** MIT. Own U121-B photographed interfaces; hidden retained internals inferred. */
import {Port,materials} from '../../core/index.js';
import {THREE,box,solid,hole,rectHole,roundedRect,ring,frame,tubeRect,bar,FACE,portQuaternion} from './geometry.js';
import {spec} from './dimensions.js';
export function addConnectors(host,parent){
 const white=materials.plastic(0xdfe0d3,{roughness:.75}),black=materials.plastic(0x191e1b,{roughness:.8}),gold=materials.metal(0xb4a165,{roughness:.43}),tin=materials.metal(0xadb2a6,{roughness:.44});
 const g=new THREE.Group();g.name='U121-B own upper white Grove socket';g.position.fromArray(spec.grove.position);parent.add(g);const grove={frame:g,walls:[],contacts:[],bends:[],feet:[],tails:[]};
 for(const sign of[-1,1]){grove.walls.push(box(g,[.7,7.6,5],[sign*5.05,-3.8,0],white,'Grove actual retained sidewall'));grove.walls.push(box(g,[.6,1.4,.5],[sign*4.1,-1.8,2.1],white,'Grove actual latch shoulder'));}
 grove.floor=box(g,[9.4,7.6,.6],[0,-3.8,-2.2],white,'Grove physical floor seated on PCB');grove.stop=box(g,[9.4,.7,4.4],[0,-7.25,.3],white,'Grove actual deep receiver stop');
 for(let i=0;i<4;i++){const x=(i-1.5)*2;grove.contacts.push(box(g,[.4,6.25,.4],[x,-4.1,.1],gold,'Grove retained actual contact '+(i+1)));grove.bends.push(box(g,[.4,.4,2.6],[x,-7.25,-1.0],tin,'Grove retained downward bend '+(i+1)));grove.feet.push(box(g,[.4,1.25,.4],[x,-7.9,-2.3],tin,'Grove actual solder heel '+(i+1)));grove.tails.push(box(g,[.4,.4,1.8],[x,-8.5,-3.0],tin,'Grove square through-PCB tail '+(i+1)));}
 grove.port=host.add(new Port({id:'grove',label:'Original U121-B EXT_PORT HY2.0-4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('top'),hitSize:[10.8,1,5],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.1],order:i=>i+1},pins:spec.grove.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',scope:'Own G33/G25/5V/GND documentary only;mechanical four-core,no I2C/electrical/firmware'}}),parent);
 const j=frame(parent,'own original deep RJ45 receiving assembly',spec.ethernet.position,'bottom'),jack={frame:j,contacts:[],bends:[],tails:[],feet:[],drills:[]};
 const outer=roundedRect(17.2,13.4,.6),cavity=new THREE.Path();cavity.moveTo(-7.3,-5.3);cavity.lineTo(7.3,-5.3);cavity.lineTo(7.3,3.9);cavity.lineTo(2,3.9);cavity.lineTo(2,5.3);cavity.lineTo(-2,5.3);cavity.lineTo(-2,3.9);cavity.lineTo(-7.3,3.9);cavity.closePath();outer.holes.push(cavity);
 jack.housing=solid(j,outer,12.6,[0,0,-12.6],black,'deep RJ45 real eight-position housing and tab-keyed cavity');jack.stop=box(j,[14.5,10.5,.8],[0,0,-12.2],black,'RJ45 actual dielectric insertion stop');jack.latch=box(j,[3.6,.55,2.1],[0,4.8,-1.1],black,'RJ45 actual fixed latch retention shelf');
 for(let i=0;i<8;i++){const x=(i-3.5)*1.02;jack.contacts.push(bar(j,[x,-3.6,-1.6],[x,-4.8,-10.2],.26,gold,'RJ45 actual bent spring contact '+(i+1)));jack.bends.push(bar(j,[x,-4.8,-10.2],[x,-4.8,-14],.26,tin,'RJ45 retained contact return '+(i+1)));jack.tails.push(box(parent,[.34,.34,3.3],[x,-18,-5.85],tin,'RJ45 actual square PCB tail '+(i+1)));}
 for(const x of[-8.1,8.1]){jack.feet.push(bar(j,[x,-4.2,-11.3],[x,-4.2,-13.8],.34,tin,'RJ45 actual retained shield heel'));jack.feet.push(box(parent,[.34,.34,2.6],[x,-18.2,-5.3],tin,'RJ45 actual square shield mounting tail'));}
 jack.port=host.add(new Port({id:'ethernet',label:'Original U121-B passive 8P RJ45',connector:'rj45',position:spec.ethernet.position,quaternion:portQuaternion('bottom'),hitSize:[17.2,1,13.4],meta:{role:'visual-connector',physicalContacts:8,scope:'Passive mechanical RJ45 only;no Ethernet/link/PoE/power or electrical simulation'}}),parent);
 const headers={};for(const[id,d]of Object.entries(spec.headers)){const h=frame(parent,id+' actual three-position female receiver',d.position,'back'),part={frame:h,contacts:[],bends:[],tails:[],bores:[]};const s=roundedRect(3,8.2,.2);for(let i=0;i<3;i++)rectHole(s,1.15,1.15,.08,0,(i-1)*2.54);part.housing=solid(h,s,3.4,[0,0,-3.4],black,id+' actual three drilled socket walls');for(let i=0;i<3;i++){const y=(i-1)*2.54;part.bores.push(box(h,[1.12,1.12,.3],[0,y,-3.25],black,id+' real deep socket stop'));for(const sign of[-1,1])part.contacts.push(box(h,[.14,.75,2.1],[sign*.4,y,-1.95],gold,id+' actual opposed retained spring'));part.bends.push(box(h,[1.0,.4,.4],[0,y,-3.0],tin,id+' actual retained spring bend'));part.tails.push(box(parent,[.34,.34,1.9],[d.position[0],d.position[1]-y,-5.25],tin,id+' actual square through-PCB tail'));}
 part.port=host.add(new Port({id,label:'Original U121-B '+d.pins.join('/'),connector:'poecam-service-3p',position:d.position,quaternion:portQuaternion('back'),hitSize:[3,1,8.2],pins:d.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',physicalContacts:3,scope:'Own actual female three-pin mechanical receiver only;no EN/reset/boot/UART/electrical/firmware simulation'}}),parent);headers[id]=part;}
 return{grove,jack,headers};
}
